using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using RestaurantPreview;
namespace IdleRestaurant {
 public sealed class RestaurantServiceView:MonoBehaviour {
  sealed class Actor {public Person person;public CharacterController controller;public ServiceGuest guest;public GuestPhase pathPhase=(GuestPhase)(-1);public List<Vector3> path=new List<Vector3>();public Dish food;}
  sealed class Dish {public Transform root;public Renderer[] pieces;public void Portion(float remaining){for(int i=0;i<pieces.Length;i++)if(pieces[i])pieces[i].enabled=i>=Mathf.FloorToInt((1-remaining)*pieces.Length);}}
  RestaurantGame game;RestaurantWorld world;readonly List<Actor> actors=new List<Actor>();List<RestaurantSeat> seats;IReadOnlyList<Person> staff;readonly Dish[] prep=new Dish[2];Dish ready;
  public int ActiveGuests=>actors.Count(x=>x.guest!=null);public int ReservedSeats=>seats==null?0:seats.Count(x=>x.owner>=0);
  public int ServedVisuals{get;private set;}public int CompletedVisuals{get;private set;}
  public void Setup(RestaurantGame g,RestaurantWorld w,List<Person> people,IReadOnlyList<Person> workers,List<RestaurantSeat> chairs){game=g;world=w;staff=workers;seats=chairs;actors.Clear();foreach(var p in people){var c=p.root.gameObject.AddComponent<CharacterController>();c.radius=.18f;c.height=1.2f;c.center=new Vector3(0,.64f,0);c.skinWidth=.02f;c.stepOffset=.08f;c.minMoveDistance=0;actors.Add(new Actor{person=p,controller=c});p.root.gameObject.SetActive(false);}for(int i=0;i<2;i++){prep[i]=NewDish(world.room);prep[i].root.localPosition=new Vector3(-.4f+i*2.4f,1.23f,4);prep[i].root.gameObject.SetActive(false);}ready=NewDish(world.room);ready.root.localPosition=new Vector3(2,1.23f,3.45f);ready.root.gameObject.SetActive(false);foreach(var seat in seats){seat.owner=-1;if(seat.index%2==0)seat.transform.parent.gameObject.SetActive(seat.index<game.SeatCapacity);}var saved=game.State.outlets[game.State.selected].service;if(saved!=null)foreach(var guest in saved){if(guest.phase==GuestPhase.Unspawned||guest.phase==GuestPhase.Exited)continue;var actor=actors.Find(x=>x.guest==null);if(actor==null)break;actor.guest=guest;actor.person.root.gameObject.SetActive(true);actor.controller.enabled=false;actor.person.root.localPosition=new Vector3(guest.x,0,guest.z);actor.person.last=actor.person.root.localPosition;actor.controller.enabled=guest.phase!=GuestPhase.Sitting&&guest.phase!=GuestPhase.Eating&&guest.phase!=GuestPhase.Standing;if(guest.seat>=0&&guest.phase!=GuestPhase.Leaving)seats[guest.seat].owner=guest.id;}}

  Dish NewDish(Transform parent){var def=game.Catalog.outlets[game.State.selected];var root=new GameObject("Animated serving",typeof(RestaurantActorMarker)).transform;root.SetParent(parent,false);var model=Instantiate(def.food,root).transform;var pieces=model.GetComponentsInChildren<Renderer>().Where(x=>!x.sharedMaterial.name.Contains("#F8F3E7")&&!x.sharedMaterial.name.Contains("#FFFFFF")).OrderByDescending(x=>x.bounds.center.y).ToArray();return new Dish{root=root,pieces=pieces};}
  int QueueRank(ServiceGuest g,ServiceGuest[] all)=>all.Count(x=>x.id<g.id&&(x.phase==GuestPhase.Entering||x.phase==GuestPhase.Queued));
  int PickupRank(ServiceGuest g,ServiceGuest[] all)=>all.Count(x=>x.id<g.id&&x.ordered&&!x.collected&&x.phase!=GuestPhase.Exited);
  void Update(){if(game==null||!game.Family||world.shown!=game.State.selected)return;var state=game.State.outlets[game.State.selected];var all=state.service;if(all==null)return;
   foreach(var seat in seats){bool enabled=seat.index<game.SeatCapacity;if(seat.transform.parent.gameObject.activeSelf!=enabled&&seat.index%2==0)seat.transform.parent.gameObject.SetActive(enabled);}
   foreach(var g in all){if(g.phase==GuestPhase.Unspawned&&g.arrivalDelay<=state.spawnClock){var actor=actors.Find(x=>x.guest==null);if(actor==null)break;actor.guest=g;actor.pathPhase=(GuestPhase)(-1);actor.controller.enabled=false;actor.person.root.gameObject.SetActive(true);actor.person.root.localPosition=new Vector3(g.x,0,g.z);actor.person.last=actor.person.root.localPosition;actor.controller.enabled=true;game.ChangePhase(g,GuestPhase.Entering);}}
   foreach(var actor in actors){var g=actor.guest;if(g==null)continue;if(g.phase==GuestPhase.Exited){if(g.seat>=0&&seats[g.seat].owner==g.id)seats[g.seat].owner=-1;if(actor.food!=null)Destroy(actor.food.root.gameObject);actor.food=null;actor.person.root.gameObject.SetActive(false);actor.guest=null;CompletedVisuals++;continue;}
    Vector3 pos=actor.person.root.localPosition;HumanMotion motion=HumanMotion.Idle;float facing=float.NaN,progress=0;bool walk=false;
    switch(g.phase){
     case GuestPhase.Entering:case GuestPhase.Queued:{var target=new Vector3(-4.15f,0,2.7f-QueueRank(g,all)*.65f);Move(actor,target);motion=HumanMotion.Waiting;if(Vector3.Distance(actor.person.root.localPosition,target)<.04f){if(g.phase==GuestPhase.Entering)game.Arrive(g);if(QueueRank(g,all)==0&&!all.Any(x=>x.phase==GuestPhase.Ordering||x.phase==GuestPhase.ToOrder))game.ChangePhase(g,GuestPhase.ToOrder);}break;}
     case GuestPhase.ToOrder:SetPath(actor,new Vector3(-4.15f,0,2.85f),new Vector3(-2.8f,0,2.85f));walk=true;break;
     case GuestPhase.Ordering:motion=HumanMotion.Ordering;facing=180;break;
     case GuestPhase.ToPickup:SetPath(actor,new Vector3(-2.8f,0,2.2f),new Vector3(3.8f,0,2.2f),new Vector3(3.8f,0,2.85f),new Vector3(2+Math.Min(3,PickupRank(g,all))*.55f,0,2.85f));walk=true;break;
     case GuestPhase.WaitingFood:{int rank=PickupRank(g,all);var target=new Vector3(2+Math.Min(3,rank)*.55f,0,2.85f);Move(actor,target);facing=180;motion=HumanMotion.Waiting;if(rank==0&&g.foodReady&&Vector3.Distance(actor.person.root.localPosition,target)<.04f)game.ChangePhase(g,GuestPhase.Receiving);break;}
     case GuestPhase.Receiving:motion=HumanMotion.Receiving;facing=180;EnsureFood(actor);progress=(float)(g.clock/game.Balance.pickupSeconds);actor.food.root.position=Vector3.Lerp(world.room.TransformPoint(new Vector3(2,1.23f,3.45f)),actor.person.body.TransformPoint(new Vector3(0,.93f,-.45f)),Mathf.SmoothStep(0,1,progress));break;
     case GuestPhase.ToSeat:{EnsureFood(actor);if(g.seat<0){var seat=seats.FirstOrDefault(x=>x.Available);if(seat==null){motion=HumanMotion.Carrying;break;}g.seat=seat.index;seat.owner=g.id;}var chair=seats[g.seat];SetPath(actor,new Vector3(2,0,2.35f),new Vector3(-.25f,0,2.35f),new Vector3(-.25f,0,chair.Approach.z),chair.Approach);walk=true;motion=HumanMotion.Carrying;Carry(actor);break;}
     case GuestPhase.Sitting:{var chair=seats[g.seat];actor.controller.enabled=false;progress=Mathf.Clamp01((float)(g.clock/game.Balance.sitSeconds));actor.person.root.localPosition=Vector3.Lerp(chair.Approach,chair.centre+Vector3.up*.04f,Mathf.SmoothStep(0,1,progress));facing=chair.yaw;motion=HumanMotion.Sitting;Carry(actor);break;}
     case GuestPhase.Eating:{var chair=seats[g.seat];actor.controller.enabled=false;actor.person.root.localPosition=chair.centre+Vector3.up*.04f;facing=chair.yaw;motion=HumanMotion.Eating;EnsureFood(actor);actor.food.root.SetParent(world.room,true);actor.food.root.localPosition=chair.plate;actor.food.root.localRotation=Quaternion.identity;float biteProgress=Mathf.Clamp01((float)(g.clock/game.MealDuration(world.shown)));float remaining=1-Mathf.Floor(biteProgress*4)/4;actor.food.Portion(remaining);break;}
     case GuestPhase.Standing:{var chair=seats[g.seat];actor.controller.enabled=false;progress=Mathf.Clamp01((float)(g.clock/game.Balance.standSeconds));actor.person.root.localPosition=Vector3.Lerp(chair.centre+Vector3.up*.04f,chair.Approach,Mathf.SmoothStep(0,1,progress));facing=chair.yaw;motion=HumanMotion.Standing;if(actor.food!=null)actor.food.Portion(0);if(progress>=1){chair.owner=-1;Carry(actor);actor.controller.enabled=true;game.ChangePhase(g,GuestPhase.Leaving);ServedVisuals++;}break;}
     case GuestPhase.Leaving:{var chair=seats[g.seat];SetPath(actor,new Vector3(chair.centre.x,0,chair.centre.z-1.1f),new Vector3(.25f,0,chair.centre.z-1.1f),new Vector3(.25f,0,-4.8f),new Vector3(4.4f,0,-5.2f));walk=true;motion=HumanMotion.Leaving;Carry(actor);actor.food.Portion(0);progress=(float)g.clock;break;}
    }
    if(walk){if(g.waypoint<actor.path.Count){Move(actor,actor.path[g.waypoint]);if(Vector3.Distance(actor.person.root.localPosition,actor.path[g.waypoint])<.04f)g.waypoint++;}if(g.waypoint>=actor.path.Count)game.Arrive(g);if(motion==HumanMotion.Idle)motion=HumanMotion.Walking;}
    pos=actor.person.root.localPosition;RestaurantAnimation.Pose(actor.person,motion,Time.time+g.variant*.71f,pos,facing,g.variant,progress,game.State.reducedMotion);g.x=pos.x;g.z=pos.z;
   }
   UpdateKitchen(all);
  }
  void EnsureFood(Actor a){if(a.food==null)a.food=NewDish(world.room);}
  void Carry(Actor a){EnsureFood(a);a.food.root.SetParent(a.person.body,false);a.food.root.localPosition=new Vector3(0,.93f,-.45f);a.food.root.localScale=Vector3.one*.8f;a.food.root.localRotation=Quaternion.identity;}
  void SetPath(Actor a,params Vector3[] points){if(a.pathPhase==a.guest.phase)return;a.pathPhase=a.guest.phase;a.path.Clear();a.path.AddRange(points);}
  void Move(Actor a,Vector3 target){if(!a.controller.enabled)return;Vector3 delta=target-a.person.root.localPosition;delta.y=0;float speed=(float)game.WalkingSpeed(world.shown);a.controller.Move(Vector3.ClampMagnitude(delta,speed*Time.deltaTime));}
  void UpdateKitchen(ServiceGuest[] all){var cooking=all.Where(x=>x.ordered&&!x.foodReady).Take(2).ToArray();for(int i=0;i<2;i++){bool busy=i<cooking.Length;prep[i].root.gameObject.SetActive(busy);if(busy){float t=Mathf.Clamp01((float)(cooking[i].cookClock/game.CookDuration(world.shown)));prep[i].Portion(t);prep[i].root.localScale=Vector3.one*(.85f+.15f*t);}var chef=staff[i+1];RestaurantAnimation.Pose(chef,busy?HumanMotion.Cooking:HumanMotion.Idle,Time.time,chef.root.localPosition,0,world.shown+i,0,game.State.reducedMotion);}var front=all.FirstOrDefault(x=>x.foodReady&&!x.collected&&x.phase!=GuestPhase.Receiving);ready.root.gameObject.SetActive(front!=null);if(front!=null)ready.Portion(1);var host=staff[0];RestaurantAnimation.Pose(host,all.Any(x=>x.phase==GuestPhase.Ordering)?HumanMotion.Ordering:HumanMotion.Idle,Time.time,host.root.localPosition,0,1,0,game.State.reducedMotion);}
 }
}
